import React from 'react';

const classes = [
  { label: 'Normal',       count: 45, color: '#4ade80', icon: '🛡️' },
  { label: 'Phone',        count: 32, color: '#60a5fa', icon: '📱' },
  { label: 'Medical Mask', count: 28, color: '#34d399', icon: '😷' },
  { label: 'Fire',         count: 8,  color: '#fb923c', icon: '🔥' },
  { label: 'Smoke',        count: 6,  color: '#94a3b8', icon: '💨' },
  { label: 'Gun',          count: 3,  color: '#f87171', icon: '🔫' },
  { label: 'Knife',        count: 2,  color: '#facc15', icon: '🔪' },
  { label: 'Falling',      count: 4,  color: '#a78bfa', icon: '🏃' },
  { label: 'Violence',     count: 2,  color: '#f43f5e', icon: '⚡' },
  { label: 'Theft Mask',   count: 1,  color: '#fb923c', icon: '🎭' },
];

export default function DetectionSummary() {
  return (
    <div style={{ marginBottom: 12 }}>
      <div style={{ fontSize: 11, fontWeight: 700, color: '#94a3b8', textTransform: 'uppercase', letterSpacing: '.5px', marginBottom: 8 }}>
        Detection Summary <span style={{ color: '#64748b', fontWeight: 400, textTransform: 'none' }}>(Today)</span>
      </div>
      <div style={{ display: 'flex', gap: 5, overflowX: 'auto', paddingBottom: 4 }}>
        {classes.map((c, i) => (
          <div key={i} style={{
            background: '#151d2e', border: '1px solid #1e2d47',
            borderRadius: 6, padding: '8px 10px',
            textAlign: 'center', minWidth: 70, flexShrink: 0
          }}>
            <span style={{ fontSize: 20, display: 'block', marginBottom: 4 }}>{c.icon}</span>
            <span style={{ fontSize: 9, fontWeight: 600, textTransform: 'uppercase', color: c.color, display: 'block', letterSpacing: '.3px' }}>
              {c.label}
            </span>
            <span style={{ fontSize: 18, fontWeight: 700, color: c.color, display: 'block', marginTop: 2 }}>
              {c.count}
            </span>
          </div>
        ))}
      </div>
    </div>
  );
}
